88 struct ID3DX12PipelineParserCallbacks
89 {
90     // Subobject Callbacks
91     virtual void FlagsCb(D3D12_PIPELINE_STATE_FLAGS) {}
92     virtual void NodeMaskCb(UINT) {}
93     virtual void RootSignatureCb(ID3D12RootSignature*) {}
94     virtual void InputLayoutCb(const D3D12_INPUT_LAYOUT_DESC&) {}
95     virtual void IBStripCutValueCb(D3D12_INDEX_BUFFER_STRIP_CUT_VALUE) {}
96     virtual void PrimitiveTopologyTypeCb(D3D12_PRIMITIVE_TOPOLOGY_TYPE) {}
97     virtual void VSCb(const D3D12_SHADER_BYTECODE&) {}
98     virtual void GSCb(const D3D12_SHADER_BYTECODE&) {}
99     virtual void StreamOutputCb(const D3D12_STREAM_OUTPUT_DESC&) {}
100     virtual void HSCb(const D3D12_SHADER_BYTECODE&) {}
101     virtual void DSCb(const D3D12_SHADER_BYTECODE&) {}
102     virtual void PSCb(const D3D12_SHADER_BYTECODE&) {}
103     virtual void CSCb(const D3D12_SHADER_BYTECODE&) {}
104     virtual void ASCb(const D3D12_SHADER_BYTECODE&) {}
105     virtual void MSCb(const D3D12_SHADER_BYTECODE&) {}
106     virtual void BlendStateCb(const D3D12_BLEND_DESC&) {}
107     virtual void DepthStencilStateCb(const D3D12_DEPTH_STENCIL_DESC&) {}
108     virtual void DepthStencilState1Cb(const D3D12_DEPTH_STENCIL_DESC1&) {}
109 #if defined(D3D12_SDK_VERSION) && (D3D12_SDK_VERSION >= 606)
110     virtual void DepthStencilState2Cb(const D3D12_DEPTH_STENCIL_DESC2&) {}
111 #endif
112     virtual void DSVFormatCb(DXGI_FORMAT) {}
113     virtual void RasterizerStateCb(const D3D12_RASTERIZER_DESC&) {}
114 #if defined(D3D12_SDK_VERSION) && (D3D12_SDK_VERSION >= 608)
115     virtual void RasterizerState1Cb(const D3D12_RASTERIZER_DESC1&) {}
116 #endif
117 #if defined(D3D12_SDK_VERSION) && (D3D12_SDK_VERSION >= 610)
118     virtual void RasterizerState2Cb(const D3D12_RASTERIZER_DESC2&) {}
119 #endif
120     virtual void RTVFormatsCb(const D3D12_RT_FORMAT_ARRAY&) {}
121     virtual void SampleDescCb(const DXGI_SAMPLE_DESC&) {}
122     virtual void SampleMaskCb(UINT) {}
123     virtual void ViewInstancingCb(const D3D12_VIEW_INSTANCING_DESC&) {}
124     virtual void CachedPSOCb(const D3D12_CACHED_PIPELINE_STATE&) {}
125 
126     // Error Callbacks
127     virtual void ErrorBadInputParameter(UINT /*ParameterIndex*/) {}
128     virtual void ErrorDuplicateSubobject(D3D12_PIPELINE_STATE_SUBOBJECT_TYPE /*DuplicateType*/) {}
129     virtual void ErrorUnknownSubobject(UINT /*UnknownTypeValue*/) {}
130 #if defined(D3D12_SDK_VERSION) && (D3D12_SDK_VERSION >= 613)
131     virtual void FinalizeCb() {}
132 #endif
133 
134     virtual ~ID3DX12PipelineParserCallbacks() = default;
135 };
