169         : Flags(Desc.Flags)
170         , NodeMask(Desc.NodeMask)
171         , pRootSignature(Desc.pRootSignature)
172         , InputLayout(Desc.InputLayout)
173         , IBStripCutValue(Desc.IBStripCutValue)
174         , PrimitiveTopologyType(Desc.PrimitiveTopologyType)
175         , VS(Desc.VS)
176         , GS(Desc.GS)
177         , StreamOutput(Desc.StreamOutput)
178         , HS(Desc.HS)
179         , DS(Desc.DS)
180         , PS(Desc.PS)
181         , BlendState(CD3DX12_BLEND_DESC(Desc.BlendState))
182         , DepthStencilState(CD3DX12_DEPTH_STENCIL_DESC2(Desc.DepthStencilState))
183         , DSVFormat(Desc.DSVFormat)
184         , RasterizerState(CD3DX12_RASTERIZER_DESC2(Desc.RasterizerState))
185         , RTVFormats(CD3DX12_RT_FORMAT_ARRAY(Desc.RTVFormats, Desc.NumRenderTargets))
186         , SampleDesc(Desc.SampleDesc)
187         , SampleMask(Desc.SampleMask)
188         , CachedPSO(Desc.CachedPSO)
189         , ViewInstancingDesc(CD3DX12_VIEW_INSTANCING_DESC(CD3DX12_DEFAULT()))
190     {}
191     CD3DX12_PIPELINE_STATE_STREAM5(const D3DX12_MESH_SHADER_PIPELINE_STATE_DESC& Desc) noexcept
192         : Flags(Desc.Flags)
193         , NodeMask(Desc.NodeMask)
194         , pRootSignature(Desc.pRootSignature)
195         , PrimitiveTopologyType(Desc.PrimitiveTopologyType)
196         , PS(Desc.PS)
197         , AS(Desc.AS)
198         , MS(Desc.MS)
199         , BlendState(CD3DX12_BLEND_DESC(Desc.BlendState))
200         , DepthStencilState(CD3DX12_DEPTH_STENCIL_DESC2(Desc.DepthStencilState))
201         , DSVFormat(Desc.DSVFormat)
202         , RasterizerState(CD3DX12_RASTERIZER_DESC2(Desc.RasterizerState))
203         , RTVFormats(CD3DX12_RT_FORMAT_ARRAY(Desc.RTVFormats, Desc.NumRenderTargets))
204         , SampleDesc(Desc.SampleDesc)
205         , SampleMask(Desc.SampleMask)
206         , CachedPSO(Desc.CachedPSO)
207         , ViewInstancingDesc(CD3DX12_VIEW_INSTANCING_DESC(CD3DX12_DEFAULT()))
208     {}
209     CD3DX12_PIPELINE_STATE_STREAM5(const D3D12_COMPUTE_PIPELINE_STATE_DESC& Desc) noexcept
210         : Flags(Desc.Flags)
211         , NodeMask(Desc.NodeMask)
212         , pRootSignature(Desc.pRootSignature)
213         , CS(CD3DX12_SHADER_BYTECODE(Desc.CS))
214         , CachedPSO(Desc.CachedPSO)
215     {
216         static_cast<D3D12_DEPTH_STENCIL_DESC2&>(DepthStencilState).DepthEnable = false;
217     }
218     CD3DX12_PIPELINE_STATE_STREAM_FLAGS Flags;
219     CD3DX12_PIPELINE_STATE_STREAM_NODE_MASK NodeMask;
220     CD3DX12_PIPELINE_STATE_STREAM_ROOT_SIGNATURE pRootSignature;
