243     D3D12_GRAPHICS_PIPELINE_STATE_DESC GraphicsDescV0() const noexcept
244     {
245         D3D12_GRAPHICS_PIPELINE_STATE_DESC D;
246         D.Flags                 = this->Flags;
247         D.NodeMask              = this->NodeMask;
248         D.pRootSignature        = this->pRootSignature;
249         D.InputLayout           = this->InputLayout;
250         D.IBStripCutValue       = this->IBStripCutValue;
251         D.PrimitiveTopologyType = this->PrimitiveTopologyType;
252         D.VS                    = this->VS;
253         D.GS                    = this->GS;
254         D.StreamOutput          = this->StreamOutput;
255         D.HS                    = this->HS;
256         D.DS                    = this->DS;
257         D.PS                    = this->PS;
258         D.BlendState            = this->BlendState;
259         D.DepthStencilState     = CD3DX12_DEPTH_STENCIL_DESC2(D3D12_DEPTH_STENCIL_DESC2(this->DepthStencilState));
260         D.DSVFormat             = this->DSVFormat;
261         D.RasterizerState       = CD3DX12_RASTERIZER_DESC2(D3D12_RASTERIZER_DESC2(this->RasterizerState));
262         D.NumRenderTargets      = D3D12_RT_FORMAT_ARRAY(this->RTVFormats).NumRenderTargets;
263         memcpy(D.RTVFormats, D3D12_RT_FORMAT_ARRAY(this->RTVFormats).RTFormats, sizeof(D.RTVFormats));
264         D.SampleDesc            = this->SampleDesc;
265         D.SampleMask            = this->SampleMask;
266         D.CachedPSO             = this->CachedPSO;
267         return D;
268     }
269     D3D12_COMPUTE_PIPELINE_STATE_DESC ComputeDescV0() const noexcept
270     {
271         D3D12_COMPUTE_PIPELINE_STATE_DESC D;
272         D.Flags                 = this->Flags;
273         D.NodeMask              = this->NodeMask;
274         D.pRootSignature        = this->pRootSignature;
275         D.CS                    = this->CS;
276         D.CachedPSO             = this->CachedPSO;
277         return D;
278     }
279 };
