1337 inline HRESULT D3DX12ParsePipelineStream(const D3D12_PIPELINE_STATE_STREAM_DESC& Desc, ID3DX12PipelineParserCallbacks* pCallbacks)
1338 {
1339     if (pCallbacks == nullptr)
1340     {
1341         return E_INVALIDARG;
1342     }
1343 
1344     if (Desc.SizeInBytes == 0 || Desc.pPipelineStateSubobjectStream == nullptr)
1345     {
1346         pCallbacks->ErrorBadInputParameter(1); // first parameter issue
1347         return E_INVALIDARG;
1348     }
1349 
1350     bool SubobjectSeen[D3D12_PIPELINE_STATE_SUBOBJECT_TYPE_MAX_VALID] = {};
1351     for (SIZE_T CurOffset = 0, SizeOfSubobject = 0; CurOffset < Desc.SizeInBytes; CurOffset += SizeOfSubobject)
1352     {
1353         BYTE* pStream = static_cast<BYTE*>(Desc.pPipelineStateSubobjectStream)+CurOffset;
1354         auto SubobjectType = *reinterpret_cast<D3D12_PIPELINE_STATE_SUBOBJECT_TYPE*>(pStream);
1355         if (SubobjectType < 0 || SubobjectType >= D3D12_PIPELINE_STATE_SUBOBJECT_TYPE_MAX_VALID)
1356         {
1357             pCallbacks->ErrorUnknownSubobject(SubobjectType);
1358             return E_INVALIDARG;
1359         }
1360         if (SubobjectSeen[D3DX12GetBaseSubobjectType(SubobjectType)])
1361         {
1362             pCallbacks->ErrorDuplicateSubobject(SubobjectType);
1363             return E_INVALIDARG; // disallow subobject duplicates in a stream
1364         }
1365         SubobjectSeen[SubobjectType] = true;
1366         switch (SubobjectType)
1367         {
1368         case D3D12_PIPELINE_STATE_SUBOBJECT_TYPE_ROOT_SIGNATURE:
1369             pCallbacks->RootSignatureCb(*reinterpret_cast<decltype(CD3DX12_PIPELINE_STATE_STREAM::pRootSignature)*>(pStream));
1370             SizeOfSubobject = sizeof(CD3DX12_PIPELINE_STATE_STREAM::pRootSignature);
1371             break;
1372         case D3D12_PIPELINE_STATE_SUBOBJECT_TYPE_VS:
1373             pCallbacks->VSCb(*reinterpret_cast<decltype(CD3DX12_PIPELINE_STATE_STREAM::VS)*>(pStream));
1374             SizeOfSubobject = sizeof(CD3DX12_PIPELINE_STATE_STREAM::VS);
1375             break;
1376         case D3D12_PIPELINE_STATE_SUBOBJECT_TYPE_PS:
1377             pCallbacks->PSCb(*reinterpret_cast<decltype(CD3DX12_PIPELINE_STATE_STREAM::PS)*>(pStream));
1378             SizeOfSubobject = sizeof(CD3DX12_PIPELINE_STATE_STREAM::PS);
1379             break;
1380         case D3D12_PIPELINE_STATE_SUBOBJECT_TYPE_DS:
1381             pCallbacks->DSCb(*reinterpret_cast<decltype(CD3DX12_PIPELINE_STATE_STREAM::DS)*>(pStream));
1382             SizeOfSubobject = sizeof(CD3DX12_PIPELINE_STATE_STREAM::DS);
1383             break;
1384         case D3D12_PIPELINE_STATE_SUBOBJECT_TYPE_HS:
1385             pCallbacks->HSCb(*reinterpret_cast<decltype(CD3DX12_PIPELINE_STATE_STREAM::HS)*>(pStream));
1386             SizeOfSubobject = sizeof(CD3DX12_PIPELINE_STATE_STREAM::HS);
1387             break;
1388         case D3D12_PIPELINE_STATE_SUBOBJECT_TYPE_GS:
1389             pCallbacks->GSCb(*reinterpret_cast<decltype(CD3DX12_PIPELINE_STATE_STREAM::GS)*>(pStream));
1390             SizeOfSubobject = sizeof(CD3DX12_PIPELINE_STATE_STREAM::GS);
1391             break;
