1393             pCallbacks->CSCb(*reinterpret_cast<decltype(CD3DX12_PIPELINE_STATE_STREAM::CS)*>(pStream));
1394             SizeOfSubobject = sizeof(CD3DX12_PIPELINE_STATE_STREAM::CS);
1395             break;
1396         case D3D12_PIPELINE_STATE_SUBOBJECT_TYPE_AS:
1397             pCallbacks->ASCb(*reinterpret_cast<decltype(CD3DX12_PIPELINE_STATE_STREAM2::AS)*>(pStream));
1398             SizeOfSubobject = sizeof(CD3DX12_PIPELINE_STATE_STREAM2::AS);
